import{_ as e,c as r,o as t,ae as l}from"./chunks/framework.C165SkQ3.js";const o="/help/assets/rulelist.DyvAbM8L.jpeg",i="/help/assets/ruleedit.CvZ7c6Yb.png",m=JSON.parse('{"title":"转发规则","description":"","frontmatter":{},"headers":[],"relativePath":"docs/rule/README.md","filePath":"docs/rule/README.md"}'),s={name:"docs/rule/README.md"};function h(n,a,d,c,u,p){return t(),r("div",null,a[0]||(a[0]=[l('<h1 id="转发规则" tabindex="-1">转发规则 <a class="header-anchor" href="#转发规则" aria-label="Permalink to &quot;转发规则&quot;">​</a></h1><img src="'+o+'"> ## 规则导入 可以导入远程规则、本地规则。方便团队之间共享规则文件。 导入gitlab上的远程规则时，确保已经配置了gitlab token <h2 id="规则导出" tabindex="-1">规则导出 <a class="header-anchor" href="#规则导出" aria-label="Permalink to &quot;规则导出&quot;">​</a></h2><p>将规则文件导出，放到gitlab上，方便别人导入。</p><h2 id="规则配置" tabindex="-1">规则配置 <a class="header-anchor" href="#规则配置" aria-label="Permalink to &quot;规则配置&quot;">​</a></h2><p>zanProxy中一个规则集可对应多个规则，每个规则集和每个规则都可单独配置是否生效。(如a规则在A规则集下，当A规则不生效时，无论a规则是否被勾选，都不生效)。 <img src="'+i+'"></p><h2 id="rule编辑界面" tabindex="-1">rule编辑界面 <a class="header-anchor" href="#rule编辑界面" aria-label="Permalink to &quot;rule编辑界面&quot;">​</a></h2><h3 id="条件" tabindex="-1">条件 <a class="header-anchor" href="#条件" aria-label="Permalink to &quot;条件&quot;">​</a></h3><p>条件框分给两个组成部分</p><ul><li>请求方式: 请求方式中可以选择包含GET，POST，PUT以及全部，你可以选择不同的请求方式对你需要转发的请求进行定义。</li><li>匹配规则</li></ul><h4 id="匹配过程" tabindex="-1">匹配过程 <a class="header-anchor" href="#匹配过程" aria-label="Permalink to &quot;匹配过程&quot;">​</a></h4><p>匹配规则为该请求是否被zanProxy所转发的主要判定方式。其判定规则如下：</p><ol><li>优先将匹配规则当成一个字符去匹配所有请求，当某一请求的url中包含匹配规则，则视为该请求符合该匹配规则。</li><li>当规则1无法匹配时，将该匹配规则实例化为一个正则表达式，再对所有请求进行匹配（RegExp.prototype.test方法）。</li></ol><h3 id="动作-转发请求" tabindex="-1">动作：转发请求 <a class="header-anchor" href="#动作-转发请求" aria-label="Permalink to &quot;动作：转发请求&quot;">​</a></h3><p>将请求转发到本地、或者另一个url</p><h3 id="动作-返回自定义数据" tabindex="-1">动作：返回自定义数据 <a class="header-anchor" href="#动作-返回自定义数据" aria-label="Permalink to &quot;动作：返回自定义数据&quot;">​</a></h3><p>将指定的数据文件返回给浏览器</p><h3 id="动作-修改返回body" tabindex="-1">动作：修改返回body <a class="header-anchor" href="#动作-修改返回body" aria-label="Permalink to &quot;动作：修改返回body&quot;">​</a></h3><ul><li>可以为html中的js、css资源请求后面加上时间戳，避免使用缓存数据。</li><li>可以将数据以jsonp的方式返回</li></ul><h3 id="进阶" tabindex="-1">进阶 <a class="header-anchor" href="#进阶" aria-label="Permalink to &quot;进阶&quot;">​</a></h3><p>在使用正则写匹配规则时，zanProxy支持在处理类型的转发中写$占位符，用于替换为正则匹配后第N个获取组。<br> e.g.<br> 请求url为：<a href="https://b.yzcdn.cn/v2/build/wap/showcase/sku_58590c11af.js" target="_blank" rel="noreferrer">https://b.yzcdn.cn/v2/build/wap/showcase/sku_58590c11af.js</a><br> 要拦截的请求的url特征为：build/wap/(.<em>?)<em>[^</em>]</em>$<br> 请求转发路径为：&lt;%=wapproject%&gt;/js/$1/main.js。<br> 则最终请求路径中的$1将被替换为showcase/sku</p>',22)]))}const _=e(s,[["render",h]]);export{m as __pageData,_ as default};
